// CoreControlServer is the server API for CoreControl service.
// All implementations must embed UnimplementedCoreControlServer
// for forward compatibility.
//
// CoreControl is the local control-plane API for the Sora core service.
type CoreControlServer interface {
	Connect(context.Context, *ConnectRequest) (*ConnectResponse, error)
	Disconnect(context.Context, *DisconnectRequest) (*DisconnectResponse, error)
	GetStatus(context.Context, *GetStatusRequest) (*GetStatusResponse, error)
	WatchEvents(*WatchEventsRequest, grpc.ServerStreamingServer[CoreEvent]) error
	ParseImport(context.Context, *ParseImportRequest) (*ParseImportResponse, error)
	FetchSubscription(context.Context, *FetchSubscriptionRequest) (*FetchSubscriptionResponse, error)
	ProbeServers(*ProbeServersRequest, grpc.ServerStreamingServer[ProbeResult]) error
	GetStats(context.Context, *GetStatsRequest) (*GetStatsResponse, error)
	RunDiagnostics(context.Context, *RunDiagnosticsRequest) (*RunDiagnosticsResponse, error)
	ExportDiagnostics(context.Context, *ExportDiagnosticsRequest) (*ExportDiagnosticsResponse, error)
	SetKillSwitch(context.Context, *SetKillSwitchRequest) (*SetKillSwitchResponse, error)
	Handshake(context.Context, *HandshakeRequest) (*HandshakeResponse, error)
	// Since 1.3. What the "About" screen shows about the core. Nothing in it is
	// personal, so it needs no authenticator.
	GetAbout(context.Context, *GetAboutRequest) (*GetAboutResponse, error)
	// Since 1.3. The routing presets and what each of them sends direct.
	GetRoutingPresets(context.Context, *GetRoutingPresetsRequest) (*GetRoutingPresetsResponse, error)
	// Since 1.3. The log center: one bounded in-memory record of the core and
	// every engine. Every call needs the control authenticator, because the
	// record and the connection list describe where a person goes.
	QueryLogs(context.Context, *QueryLogsRequest) (*QueryLogsResponse, error)
	WatchLogs(*WatchLogsRequest, grpc.ServerStreamingServer[LogEntry]) error
	ExportLogs(context.Context, *ExportLogsRequest) (*ExportLogsResponse, error)
	ClearLogs(context.Context, *ClearLogsRequest) (*ClearLogsResponse, error)
	GetLogSettings(context.Context, *GetLogSettingsRequest) (*GetLogSettingsResponse, error)
	SetLogSettings(context.Context, *SetLogSettingsRequest) (*SetLogSettingsResponse, error)
	// Since 1.3. The connection center: live connections of the session.
	ListConnections(context.Context, *ListConnectionsRequest) (*ListConnectionsResponse, error)
	// The configuration behind one server, with its credentials, for the person
	// who owns it. Needs the control authenticator.
	GetServerConfig(context.Context, *GetServerConfigRequest) (*GetServerConfigResponse, error)
	CloseConnection(context.Context, *CloseConnectionRequest) (*CloseConnectionResponse, error)
	// Since 1.3. Subscriptions the core keeps and updates by itself, so they stay
	// current while the interface is closed. The link of a subscription is its
	// credential: the core stores it encrypted and omits it from states.
	SaveSubscription(context.Context, *SaveSubscriptionRequest) (*SaveSubscriptionResponse, error)
	ListSubscriptions(context.Context, *ListSubscriptionsRequest) (*ListSubscriptionsResponse, error)
	DeleteSubscription(context.Context, *DeleteSubscriptionRequest) (*DeleteSubscriptionResponse, error)
	RefreshSubscription(context.Context, *RefreshSubscriptionRequest) (*RefreshSubscriptionResponse, error)
	WatchSubscriptions(*WatchSubscriptionsRequest, grpc.ServerStreamingServer[SubscriptionState]) error
	// Since 1.6. Returns the stored subscription link only on an authenticated
	// explicit request to open its page. Clients must not cache or log it.
	GetSubscriptionLink(context.Context, *GetSubscriptionLinkRequest) (*GetSubscriptionLinkResponse, error)
	// Since 1.14, with the "device-identity" capability. The device identifier
	// saved subscriptions send; both calls need the control authenticator.
	GetDeviceIdentity(context.Context, *GetDeviceIdentityRequest) (*GetDeviceIdentityResponse, error)
	SetDeviceIdentity(context.Context, *SetDeviceIdentityRequest) (*SetDeviceIdentityResponse, error)
	// PutSecret and DeleteSecret manage the credential material the core keeps.
	// They exist because the rest of the contract carries only references: a plan
	// names a secret, and these two calls are the only way a secret ever reaches
	// the core. Keeping them separate means no other method can be turned into a
	// way to read a stored credential.
	PutSecret(context.Context, *PutSecretRequest) (*PutSecretResponse, error)
	DeleteSecret(context.Context, *DeleteSecretRequest) (*DeleteSecretResponse, error)
	// Since 1.8. DNS leak diagnostics: which resolvers the session uses versus
	// what the OS would use, and whether the kill switch covers DNS. Requires
	// the control authenticator: the answers describe the machine's network.
	CheckDnsLeaks(context.Context, *CheckDnsLeaksRequest) (*CheckDnsLeaksResponse, error)
	// Since 1.9. Throughput benchmark: measures real download goodput through
	// each server by spinning up a temporary engine session. Streams progress
	// samples; each server reports done=true once. Requires the control
	// authenticator: benchmarks burn traffic and spawn engine processes.
	BenchmarkServers(*BenchmarkServersRequest, grpc.ServerStreamingServer[BandwidthSample]) error
	// Since 1.9. RETIRED (2026-10-20, PASS1 M3): no client ever called
	// this RPC - the app keeps its benchmark history locally - so the
	// core no longer implements it (callers get Unimplemented) and the
	// stored history behind it was removed. The messages stay for wire
	// compatibility; do not build on this method.
	GetBenchmarks(context.Context, *GetBenchmarksRequest) (*GetBenchmarksResponse, error)
	// Since 1.10. Network profiles with automatic matching: the core watches
	// the network fingerprint and reports ProfileMatched events when a saved
	// profile matches the current network. Requires the control authenticator:
	// profiles describe the machine's networks.
	ListProfiles(context.Context, *ListProfilesRequest) (*ListProfilesResponse, error)
	SaveProfile(context.Context, *SaveProfileRequest) (*SaveProfileResponse, error)
	DeleteProfile(context.Context, *DeleteProfileRequest) (*DeleteProfileResponse, error)
	GetNetworkFingerprint(context.Context, *GetNetworkFingerprintRequest) (*GetNetworkFingerprintResponse, error)
	// Since 1.10. Probes a proxy chain of 2-3 servers: per-hop reachability,
	// the summed latency estimate, and which installed engines can carry it.
	// Requires the control authenticator: probes burn traffic.
	ProbeChain(context.Context, *ProbeChainRequest) (*ProbeChainResponse, error)
	mustEmbedUnimplementedCoreControlServer()
}

